from collections import deque, Counter
R,C=25,25
seen=set(); pieces=[]
for r in range(R):
  for c in range(10,25):
    if grid[r][c]!=4 and (r,c) not in seen:
      q=[(r,c)]; seen.add((r,c)); cells=[]
      for x,y in q:
        cells.append((x,y,grid[x][y]))
        for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
          if 0<=nx<R and 10<=ny<C and grid[nx][ny]!=4 and (nx,ny) not in seen:
            seen.add((nx,ny));q.append((nx,ny))
      minr=min(x for x,y,v in cells);minc=min(y for x,y,v in cells)
      shape=tuple(sorted((x-minr,y-minc,v) for x,y,v in cells))
      pieces.append(shape)
[(len(p), (max(x for x,y,v in p)+1, max(y for x,y,v in p)+1), Counter(v for x,y,v in p)) for p in pieces],len(pieces),sum(map(len,pieces))

target={(r,c) for r in range(R) for c in range(10) if grid[r][c]==9}
# label tile coordinates local, origin
pieces_coords=[]
for p in pieces:
  pieces_coords.append([(x,y,v) for x,y,v in p])

def gen_placements(rots=False):
  allpls=[]
  for i,p in enumerate(pieces_coords):
    variants=[]
    cells=[(x,y,v) for x,y,v in p]
    variants.append(cells)
    if rots:
      # allow rotations around cell grid preserving colors
      for k in range(1,4):
        t=cells
        for _ in range(k): t=[(y,-x,v) for x,y,v in t]
        mr=min(x for x,y,v in t); mc=min(y for x,y,v in t)
        variants.append([(x-mr,y-mc,v) for x,y,v in t])
    normvar=[]
    for v in variants:
      mr=min(x for x,y,col in v); mc=min(y for x,y,col in v)
      vv=tuple(sorted((x-mr,y-mc,col) for x,y,col in v))
      if vv not in normvar:normvar.append(vv)
    pl=[]
    for v in normvar:
      h=max(x for x,y,col in v)+1; w=max(y for x,y,col in v)+1
      for rr in range(R-h+1):
        for cc in range(10-w+1):
          coords={(rr+x,cc+y) for x,y,col in v}
          if coords <= target:
            mask=sum(1<<(x*10+y) for x,y in coords)
            pl.append((mask,i,rr,cc,v))
    allpls.append(pl)
  return allpls
